
/**
 * Abstract:
 * ahb_master_directed_sequence is used by test to provide initiator
 * scenario information to the Master agent present in the System Env.
 * This class defines a sequence in which a AHB WRITE followed by a AHB READ
 * sequence is generated by assigning values to the transactions rather than
 * randomization, and then transmitted using `uvm_send.
 *
 * Execution phase: main_phase
 * Sequencer: Master agent sequencer
 */

`ifndef GUARD_AHB_MASTER_DIRECTED_SEQUENCE_SV
`define GUARD_AHB_MASTER_DIRECTED_SEQUENCE_SV

class ahb_seqs extends svt_ahb_master_transaction_base_sequence;

  /** UVM Object Utility macro */
  `uvm_object_utils(ahb_seqs)

  /** Class Constructor */
  function new(string name="ahb_seqs");
    super.new(name);
  endfunction
  
virtual task body();
endtask

endclass

class ahb_dsireg_seqs extends ahb_seqs;

  /** UVM Object Utility macro */
  `uvm_object_utils(ahb_dsireg_seqs)

  /** Class Constructor */
  function new(string name="ahb_dsireg_seqs");
    super.new(name);
  endfunction

  virtual task body();
    svt_ahb_master_transaction svt_xtn;
    svt_xtn=svt_ahb_master_transaction::type_id::create("svt_xtn");
 
   //---------------- PAYLOAD1 ----------------//
 `uvm_do_with(svt_xtn,
        {  
          svt_xtn.xact_type    == svt_ahb_transaction::WRITE;
          svt_xtn.addr         == 32'h4000_0000;
          svt_xtn.burst_type   == svt_ahb_transaction::SINGLE;
          svt_xtn.burst_size   == svt_ahb_transaction::BURST_SIZE_32BIT;
          data.size() == 1;
          data[0] == 32'h0;//buffer register
          })
   //---------------- PAYLOAD2 ----------------//
`uvm_do_with(svt_xtn,
        {  
          svt_xtn.xact_type    == svt_ahb_transaction::WRITE;
          svt_xtn.addr         == 32'h4000_0004;
          svt_xtn.burst_type   == svt_ahb_transaction::SINGLE;
          svt_xtn.burst_size   == svt_ahb_transaction::BURST_SIZE_32BIT;
          data.size() == 1;
          data[0] == 32'h7c;//short,long packet,bit per pixel
//        short_packet={8'hdd,8'hFF,ecc,16'hCAFE,dsi.dsi_reg.dsi_cmd[8:1],8'hFF,8'hcc};
//        long_packet ={8'hbb,8'hFF,crc,payload,header,8'hFF,8'haa}; 
//        header={ecc,dsi.dsi_reg.dsi_lng[16:1],dsi.dsi_reg.dsi_cmd[8:1]};
         } )
   //---------------- DSI_CMD ----------------//
 `uvm_do_with(svt_xtn,
        {  
          svt_xtn.xact_type    == svt_ahb_transaction::WRITE;
          svt_xtn.addr         == 32'h4000_0008;
          svt_xtn.burst_type   == svt_ahb_transaction::SINGLE;
          svt_xtn.burst_size   == svt_ahb_transaction::BURST_SIZE_32BIT;
          data.size() == 1;
          data[0] == 32'h3c;//length-word count
//16:1-> for word_count, Maximum RGB-888 Pixels = 21845 Pixels datas we can send
        } )   
   //---------------- DSI_LNG ----------------//
         `uvm_do_with(svt_xtn,
        {  
          svt_xtn.xact_type    == svt_ahb_transaction::WRITE;
          svt_xtn.addr         == 32'h4000_000c;
          svt_xtn.burst_type   == svt_ahb_transaction::SINGLE;
          svt_xtn.burst_size   == svt_ahb_transaction::BURST_SIZE_32BIT;
          data.size() == 1;
          data[0] == 32'h3;//ctrl register-no.of lanes
          //last 2-bits reg[1:0] for no_ofLanes{2'b00-1,2'b01-2,2'b10-3,2'b11-4}
        } )   
   //---------------- CTRL0 ----------------//
    `uvm_do_with(svt_xtn,
        {  
          svt_xtn.xact_type    == svt_ahb_transaction::WRITE;
          svt_xtn.addr         == 32'h4000_0010;
          svt_xtn.burst_type   == svt_ahb_transaction::SINGLE;
          svt_xtn.burst_size   == svt_ahb_transaction::BURST_SIZE_32BIT;
          data.size() == 1;
          data[0] == 32'h2;
        } )   

  endtask: body

endclass

